import { type ReactNode } from 'react';
import { type IntlShape } from 'react-intl';

import { _useFormControlState } from '../../../core/hooks/useFormControlState.js';
import {
  _getFormattedMinMax,
  messages,
} from '../../forms-core/time/timeParser.js';
import type { TimeframeSelectorProps } from '../TimeframeSelector.js';
import { _isOutsideRange } from '../utils/timeframe-selection.js';

/**
 * Hook used to retrieve the hasError and hint.
 * @internal
 */
export function _useTimeframeValidation(
  value: TimeframeSelectorProps['value'],
  intl: IntlShape,
  controlState: TimeframeSelectorProps['controlState'],
  required?: boolean,
  min?: string,
  max?: string,
  isInvalid?: boolean,
  hintProp?: string,
  precision?: TimeframeSelectorProps['precision'],
): {
  hasError: boolean;
  hint?: ReactNode;
} {
  let [hasError, hint] = _useFormControlState(controlState);

  if (isInvalid) {
    hasError = true;
    hint = hintProp;
  }

  if (_isOutsideRange(value, min, max)) {
    hasError = true;
    hint = intl.formatMessage(
      messages.outsideRange,
      _getFormattedMinMax(min, max, precision),
    );
  }

  if (required && !value) {
    hasError = true;
    hint = intl.formatMessage(messages.requiredTimeframe);
  }

  return { hasError, hint };
}
